const deathFlowerSheet=new Image();deathFlowerSheet.assetSrc='assets/death-flower-v1.png';
function beginDeathFlower(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'deathFlowerStillness',bespoke:true,windup:2.8,origin:{x:e.x,y:e.y},previous:{x:p.x,y:p.y},rest:0,cleared:false,fired:false};}
const deathFlowerAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e6')return deathFlowerAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='deathFlowerStillness'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=320&&clear){beginDeathFlower(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,48*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.fired&&!a.cleared){if(dist(a.origin,p)>500||!lineClear(a.origin,p)){a.cleared=true;a.clearReason='brokenLink';}else{let active=Math.max(0,Math.min(2.8,e.elapsed)-Math.max(.5,before));if(active>0){if(dist(a.previous,p)<=8*dt+1e-8)a.rest=Math.round((a.rest+active)*1e6)/1e6;else a.rest=0;if(a.rest>=1.1){a.cleared=true;a.clearReason='stillness';playSound('impact',e.x,e.y);}}}}a.previous={x:p.x,y:p.y};
 if(!a.fired&&e.elapsed>=2.8){a.fired=true;e.struck=true;if(!a.cleared)hurt(80);playSound('impact',e.x,e.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const deathFlowerDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e6'||!deathFlowerSheet.complete||!deathFlowerSheet.naturalWidth||!deathFlowerSheet.naturalHeight)return deathFlowerDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='deathFlowerStillness')f={row:2,col:a.cleared?3:e.elapsed<.5?0:e.elapsed<a.windup?1:e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=deathFlowerSheet.naturalWidth/4,sh=deathFlowerSheet.naturalHeight/3,w=230,h=w*sh/sw,anchor=[[.9,.9,.9,.9],[.87,.88,.89,.88],[.9,.9,.9,.9]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,deathFlowerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(deathFlowerSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const deathFlowerSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e6'?175:deathFlowerSizeBase(e);
const deathFlowerGroundBase=drawGroundEffects;drawGroundEffects=()=>{deathFlowerGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e6'):enemies)){let a=e.attack;if(e.species!=='r10e6'||e.hp<=0||a?.pattern!=='deathFlowerStillness'||e.elapsed>3.05||!visibleAt(p.x,p.y))continue;if(a.cleared){groundRing(e.x,e.y,28,'#91e2b4',2);continue;}let from=project(e.x,e.y),to=project(p.x,p.y);ctx.save();ctx.strokeStyle=a.fired?'#f6d5ff':'#b28ac9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(from.x,from.y-35);ctx.lineTo(to.x,to.y-30);ctx.stroke();ctx.fillStyle='#d6b9e3';ctx.fillRect(to.x-7,to.y-65,5,14);ctx.fillRect(to.x+2,to.y-65,5,14);ctx.restore();groundRing(p.x,p.y,40,'#ba93ce',2);groundRing(p.x,p.y,40*Math.min(1,a.rest/1.1),'#98efc7',3);}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e6',animateEnemy,drawRegionEnemy);
